const localize = <T,>(value: T, lang: Exclude<Lang, 'en'>): T => {
  if (typeof value === 'string') {
    const translated = replacements[lang][value];
    if (translated) return translated as T;
    return value;
  }
  if (Array.isArray(value)) return value.map((item) => localize(item, lang)) as T;
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, localize(item, lang)])) as T;
  }
  return value;
};

export const positioning: Record<Lang, Positioning> = {
  en: make(copies.en), et: localize(make(copies.et), 'et'), pl: localize(make(copies.pl), 'pl'), ru: localize(make(copies.ru), 'ru'),
};
